@Test
public void testConcurrentRegistrationOfTheSameJar() throws Exception {
    RemoteFunctionRegistry remoteFunctionRegistry = spyRemoteFunctionRegistry();
    final CountDownLatch latch1 = new CountDownLatch(1);
    final CountDownLatch latch2 = new CountDownLatch(1);
    doAnswer(invocation -> {
        String result = (String) invocation.callRealMethod();
        latch2.countDown();
        latch1.await();
        return result;
    }).doCallRealMethod().doCallRealMethod().when(remoteFunctionRegistry).addToJars(anyString(), any(RemoteFunctionRegistry.Action.class));
    final String query = String.format("create function using jar '%s'", defaultBinaryJar);
    Thread thread = new Thread(new SimpleQueryRunner(query));
    thread.start();
    latch2.await();
    try {
        String summary = "Jar with %s name is used. Action: REGISTRATION";
        testBuilder().sqlQuery(query).unOrdered().baselineColumns("ok", "summary").baselineValues(false, String.format(summary, defaultBinaryJar)).go();
        testBuilder().sqlQuery("drop function using jar '%s'", defaultBinaryJar).unOrdered().baselineColumns("ok", "summary").baselineValues(false, String.format(summary, defaultBinaryJar)).go();
    } finally {
        latch1.countDown();
        thread.join();
    }
}

